		 if(s.rotation||s.flipX||s.flipY){ctx.translate(s.x+s.w/2,s.y+s.h/2);if(s.rotation)ctx.rotate(s.rotation*Math.PI/180);ctx.scale(s.flipX?-1:1,s.flipY?-1:1);s={...s,x:-s.w/2,y:-s.h/2};}
