		  const canvas=referenceCanvas(current.size.w,current.size.h),ctx=canvas.getContext('2d');
		  if(current.fillEnabled){ctx.fillStyle=current.imageBackgroundColor;ctx.fillRect(0,0,canvas.width,canvas.height);}
