			if (v[0] === "COMBO") {
				const opt = (v.length > 1 && v[1] && v[1].options) || [];
				return Array.isArray(opt) ? opt.slice() : [];
			}
			// 形态 1 / 2：第一项就是名字数组（第二项可有可无）
			if (Array.isArray(v[0])) return v[0].slice();
